local mE=bb.rogueShare(Hve[2258])
jE=jE*(mE+(1-mE)/(1-iE.ice+iE.ice/gb.modFactor(Hve[2669])))
end
if iE.fly>0 then
jE=jE*(1-iE.fly*0.5)
end
