function W.icWinP(PP)
local QP=PP.rec or W.rec(PP.key)
local RP=W.icLost(PP.room)
local SP=RP and RP.n or 0
local TP=((tonumber(QP.wins)or 0)+(PP.p0 or W.PRIOR_WIN.castle)*2)/((tonumber(QP.runs)or 0)+2)
local UP=W.sim(PP)
local VP,WP=0,0
if UP and tonumber(UP.p)then
local XP=type(UP.trust)==Hve[2124]and UP.trust or nil
local YP=XP~=nil and not XP.ok
local ZP=YP and(tonumber(XP.ratio)or 1)>1
if not YP or(ZP and not UP.won)or(YP and not ZP and UP.won)then
local _P,aQ=pcall(gb.styleP,UP)
VP,WP=(_P and tonumber(aQ))or tonumber(UP.p),W.IC.SIM_W
end
end
return(TP*2+VP*WP)/(SP+2+WP)
end
function W.winP(bQ)
