return W.icWinP(bQ)
end
if bQ.kind==Hve[2577]and O.dailyMatch and not O.dailyLoop then
local cQ,dQ=pcall(W.needsHelp,bQ)
if cQ and dQ then
return W.MATCHED_DAILY_P
end
end
local eQ=bQ.rec
local fQ=bQ.p0 or W.PRIOR_WIN[bQ.kind]or 0.7
local gQ=W.sim(bQ)
if gQ and not(gQ.trust and not gQ.trust.ok)then
local hQ=gQ.calibrated or eQ.runs>0
local iQ=(gQ.trust and gQ.trust.ok)and 6 or(hQ and 3 or 1.5)
local jQ=(hQ or gQ.hopeless)and 0 or 2
local kQ,lQ=pcall(gb.styleP,gQ)
return(eQ.wins+fQ*jQ+(kQ and lQ or gQ.p)*iQ)/(eQ.runs+jQ+iQ)
end
return(eQ.wins+fQ*2)/(eQ.runs+2)
end
