ab.FUSE_RANK={Rare=1,Epic=2,Legendary=3}
function ab.xpFodder(Jfb)
local Kfb=N.session()
local Lfb=ab.FUSE_RANK[O.fuseXpRarity]or 2
local Mfb={[Jfb.uuid]=true,[O.evolveUnit]=true}
for Nfb,Ofb in ipairs(V.equipped())do
Mfb[Ofb.uuid]=true
end
for Pfb,Qfb in ipairs(P.savedTeam or{})do
Mfb[Qfb]=true
end
for Rfb,Sfb in ipairs(P.train and P.train.on and P.train.on.base or{})do
Mfb[Sfb]=true
end
local Tfb,Ufb={},0
for Vfb,Wfb in pairs(Kfb.profile_data.collection.owned_units)do
local Xfb=N.Units[Wfb.unit_id]
local Yfb=Xfb and ab.FUSE_RANK[Xfb.rarity]
if Yfb and Yfb<=Lfb and not Mfb[Vfb]then
local Zfb=Kfb.collection:get_unit_by_uuid(Vfb)or Wfb
if not(Wfb._locked or Zfb._locked)and not(Wfb._equipped_relic or Zfb._equipped_relic)then
local _fb,agb=pcall(N.USC.calculate_xp_gain_from_fuse,Jfb,{Zfb},Kfb)
agb=_fb and tonumber(agb)or 0
if agb>0 then
table.insert(Tfb,{uuid=Vfb,id=Wfb.unit_id,xp=agb,rarity=Xfb.rarity})
Ufb=Ufb+agb
end
end
end
end
table.sort(Tfb,function(bgb,cgb)
if bgb.xp~=cgb.xp then
return bgb.xp<cgb.xp
end
return bgb.uuid<cgb.uuid
end)
local dgb=math.max(0,kb.xpFor(Jfb.unit_id,kb.cap(Jfb))-(tonumber(Jfb.xp)or 0))
local egb,fgb={},0
for ggb,hgb in ipairs(Tfb)do
if fgb>=dgb then
break
end
table.insert(egb,hgb)
fgb=fgb+hgb.xp
end
return egb,fgb,dgb,Ufb
end
