table.insert(yyb,Ayb.uuid==oyb.uuid and fyb.u or Ayb.u)
end
local Byb,Cyb=pcall(gb.run,xyb,gb.teamFrom(yyb,xyb.map),{hpMul=1.1})
local Dyb=Byb and type(Cyb)==Hve[2124]and(Cyb.won or(xyb.infinite and(tonumber(Cyb.wave)or 0)>=0.8*W.infReach(Zxb.key)))
