function eb.upgradeGain(kDb,lDb,mDb,nDb,oDb,pDb)
local qDb,rDb=lDb[mDb],lDb[mDb+1]
local sDb=(qDb.cd>0 and qDb.damage/qDb.cd or 0)
local tDb=(rDb.cd>0 and rDb.damage/rDb.cd or 0)*V.aoe(rDb.atk,rDb.range)/math.max(0.3,V.aoe(qDb.atk,qDb.range))
local uDb=sDb>0 and kDb*(tDb/sDb-1)or(pDb or 0)
local vDb=lDb[mDb+2]
if vDb and mDb+1<lDb.max and vDb.cd>0 and rDb.cd>0 and sDb>0 then
local wDb=kDb*((vDb.damage/vDb.cd)/sDb-1)
local xDb=nDb+vDb.cost*oDb
if wDb/xDb>uDb/nDb then
uDb=uDb+(wDb/xDb*nDb-uDb)*0.5
end
end
local yDb=(rDb.range or 0)>(qDb.range or 0)and(1+((rDb.range-qDb.range)/math.max(1,qDb.range)))or 1
return math.max(0,uDb)*yDb
end
function eb.dpsFor(zDb,ADb)
if ADb<=0 then
return 0
end
local BDb={}
for CDb,DDb in ipairs(zDb)do
if not DDb.farm and not DDb.grif and DDb.gain>0 then
table.insert(BDb,DDb)
end
end
table.sort(BDb,function(EDb,FDb)
return EDb.gain/EDb.cost>FDb.gain/FDb.cost
end)
local GDb,HDb=0,0
for IDb,JDb in ipairs(BDb)do
if ADb<=0 then
break
end
HDb=JDb.gain/JDb.cost
local KDb=math.min(1,ADb/JDb.cost)
GDb=GDb+JDb.gain*KDb
ADb=ADb-JDb.cost*KDb
end
return GDb+math.max(0,ADb)*HDb*0.7
end
function eb.shieldDps(LDb,MDb,NDb,ODb,PDb,QDb,RDb)
if(ODb or 0)<=0 or(LDb or 0)<=0 or(PDb or 0)<=0 then
return LDb or 0
end
MDb,NDb,QDb=math.max(0.3,MDb or 2),math.max(1,NDb or 1),QDb or 1
local SDb=LDb*QDb*MDb/NDb
return PDb*NDb/((ODb/math.max(1,RDb or 1)+math.max(1,PDb/SDb))*MDb)/QDb
end
function eb.shieldGain(TDb,UDb,VDb,WDb,XDb,YDb,ZDb,_Db)
local aEb,bEb=V.attackInfo(UDb.atk,UDb.range),V.attackInfo(WDb.atk,WDb.range)
local cEb=eb.shieldDps(TDb,(tonumber(UDb.cd)or 2)*(ZDb or 1),aEb.n,XDb,YDb,_Db,aEb.hits)
local dEb=eb.shieldDps(VDb,(tonumber(WDb.cd)or 2)*(ZDb or 1),bEb.n,XDb,YDb,_Db,bEb.hits)
local eEb=math.max(0,((tonumber(WDb.range)or 0)-(tonumber(UDb.range)or 0))/math.max(1,tonumber(UDb.range)or 1))
return math.max(0,dEb-cEb)+cEb*eEb
end
function eb.shieldWork(fEb,gEb,hEb,iEb,jEb,kEb,lEb,mEb,nEb)
if(iEb or 0)<=0 then
return 0
end
local oEb=3*iEb*(jEb or 1)/math.max(1,kEb or 20)
if(hEb or 0)>=oEb then
return 0
end
return math.max(1,fEb or 1)*math.max(1,nEb or 1)/math.max(0.3,gEb or 2)*math.min(lEb or 0,mEb or 0)
end
function eb.holdGain(pEb,qEb,rEb,sEb)
if not pEb or(qEb or 0)<=0 then
return 0
end
local tEb,uEb=tonumber(pEb.stun)or 0,tonumber(pEb.slowTime)or 0
if tEb<=0 and uEb<=0 then
return 0
end
local vEb,wEb=tEb>0 and tEb or uEb,tEb>0 and 1 or(tonumber(pEb.slowPct)or 0.3)
local xEb=wEb*vEb/(vEb+(tonumber(pEb.ccCd)or 8))
local yEb=xEb/math.max(0.1,1-xEb)
return qEb*yEb*U.clamp(rEb or 0.5,0,1)*math.min(1,(tonumber(pEb.n)or 1)/2)/(1+(sEb or 0))
end
function eb.bleedGain(zEb,AEb,BEb,CEb)
if(zEb or 0)<=0 then
return 0
end
local DEb=AEb or 0
for EEb,FEb in ipairs(BEb or{})do
DEb=math.max(DEb,(tonumber(FEb.hp)or 0)*0.5)
end
return zEb*DEb*(CEb and 0.5 or 1)
end
function eb.bleedShare(GEb,HEb,IEb,JEb)
if GEb<=0 or not HEb then
return 0
end
if JEb then
return HEb==0 and GEb or GEb/(HEb+1)
end
return IEb<HEb and GEb/(HEb-IEb)or 0
end
function eb.keepsUp(KEb,LEb,MEb,NEb,OEb)
local PEb=KEb.coming
if not(PEb and#PEb>0 and KEb.waveSec)then
return true
end
local QEb=KEb.eff or 1
local REb=KEb.money-MEb
local SEb=(KEb.teamDps or 0)*(KEb.shieldK or 1)+(NEb or 0)*QEb+eb.dpsFor(LEb,math.max(0,REb))*QEb
local TEb=(KEb.farmNow or 0)+(OEb or 0)
local UEb=(KEb.roadSec or 130)*U.clamp(KEb.cover or 0.6,0.1,1)
local VEb=KEb.hpAlive or 0
for WEb,XEb in ipairs(PEb)do
VEb=math.max(0,VEb+XEb.hp-SEb*KEb.waveSec)
local YEb=SEb*UEb
if VEb>YEb then
return false,WEb,YEb/math.max(1,VEb)
end
if WEb< #PEb then
SEb=SEb+eb.dpsFor(LEb,(XEb.reward or 0)+TEb)*QEb*(0.85^WEb)
end
end
return true
end
function eb.decide(ZEb,_Eb)
local aFb=U.clamp(_Eb.cover or 0.6,0.1,1)
local bFb=math.max(O.clearSec,0.7*(_Eb.roadSec or 50)*aFb)
local cFb=(_Eb.clearSec or 0)>bFb
_Eb.piling=_Eb.piling and cFb
local dFb=_Eb.attackers>0 and _Eb.pressure<math.min(O.safeReach,aFb*0.75)and not _Eb.piling and not cFb
local eFb=_Eb.pressure>=math.min(O.dangerReach,aFb*0.9)or(_Eb.piling and _Eb.enemies>=18)
local fFb,gFb
for hFb,iFb in ipairs(ZEb)do
if iFb.farm then
if O.farmUnits and iFb.gain>0 then
iFb.payback=iFb.cost/iFb.gain
if _Eb.left-1>=iFb.payback+(_Eb.farmSpare or O.farmSpare)and(not fFb or iFb.payback<fFb.payback)then
fFb=iFb
end
end
else
iFb.ratio=iFb.gain/math.max(1,iFb.cost)
if not gFb or iFb.ratio>gFb.ratio then
gFb=iFb
end
end
end
if _Eb.leak and _Eb.attackers>0 then
local jFb
for kFb,lFb in ipairs(ZEb)do
local mFb=not _Eb.airLeak or(lFb.e and bb.cardAir(lFb.e.id))
if lFb.place and not lFb.farm and not lFb.idol and not lFb.grif and mFb and lFb.cost<=_Eb.money and not(lFb.e and V.allyBuff(lFb.e.id))and(not jFb or lFb.gain>jFb.gain)then
jFb=lFb
