end
end
local nFb=_Eb.future<_Eb.wantLeft*1.1
local oFb,pFb,qFb=true,nil,nil
if fFb then
oFb,pFb,qFb=eb.keepsUp(_Eb,ZEb,fFb.cost,0,fFb.gain)
end
local rFb=_Eb.coming and not eb.keepsUp(_Eb,ZEb,0,0,0)
local sFb=false
if bb.random and fFb and not eFb and _Eb.attackers>=2 and fFb.payback<=_Eb.left/3 then
local tFb=0
for uFb,vFb in ipairs(bb.mine or{})do
