local xlc,ylc
for zlc,Alc in ipairs(jb.after(hlc,vlc.choice))do
local Blc=jb.roomValue(Alc,klc)
if not xlc or Blc>xlc then
xlc,ylc=Blc,Alc
end
end
local Clc,Dlc=jb.winP(vlc)
local Elc=Dlc~=nil and Dlc.won==false
local Flc=jlc>=3 and 1 or(jlc==2 and 2 or 6)
