qlc=vlc
end
if Elc then
if not tlc or vlc.score>tlc.score then
tlc=vlc
end
elseif not slc or vlc.score>slc.score then
slc=vlc
end
end
if not rlc or vlc.score>rlc.score then
rlc=vlc
end
end
if qlc and qlc.simLost and slc then
F.log(1,Hve[4064],string.format(Hve[4065],jb.roomName(qlc),tostring(qlc.sim and qlc.sim.margin or Hve[2360]),math.floor((1-jb.lossWin())*100+0.5),jb.roomName(slc)))
elseif qlc and tlc and tlc~=qlc and tlc.oldScore>qlc.score then
F.log(1,Hve[4064],string.format(Hve[4066],jb.roomName(tlc),tostring(tlc.sim and tlc.sim.margin or Hve[2360]),jb.roomName(qlc)))
end
qlc=qlc or rlc
jb._pick={sig=plc,x=qlc,rooms=llc}
return qlc
end
