jb.ROOM_K_MAX=6
function jb.roomK(grc)
local hrc=grc~=nil and type(P.dg.roomK)==Hve[2124]and P.dg.roomK[tostring(grc)]or nil
return type(hrc)==Hve[2124]and tonumber(hrc.k)or 1
end
function jb.applyK(irc,jrc)
