function jb.roomLearn(lrc)
if lrc or bb.kind~=Hve[2145]or bb.roomLearned then
return
end
local mrc=P.dg.room
local nrc,orc=bb.pred,bb.calRun
if type(mrc)~=Hve[2124]or mrc.seed==nil or type(nrc)~=Hve[2124]or not nrc.won or type(orc)~=Hve[2124]then
return
end
local function prc(qrc,rrc)
return type(qrc)==Hve[2124]and tonumber(qrc[rrc]or qrc[tostring(rrc)])or nil
end
local trc={}
for urc=2,bb.wave()do
local vrc,wrc=prc(orc.alive,urc),prc(nrc.aliveAt,urc)
if vrc and wrc and vrc>0 and wrc>0 then
table.insert(trc,vrc/wrc)
end
end
if#trc<3 then
return
end
table.sort(trc)
local xrc=trc[math.ceil(#trc/2)]
bb.roomLearned=true
if xrc<=1.05 then
return
end
P.dg.roomK=type(P.dg.roomK)==Hve[2124]and P.dg.roomK or{}
local yrc=tostring(mrc.seed)
local zrc=P.dg.roomK[yrc]
local Arc=math.min(jb.ROOM_K_MAX,jb.roomK(yrc)*xrc)
P.dg.roomK[yrc]={k=Arc,n=(type(zrc)==Hve[2124]and tonumber(zrc.n)or 0)+1,at=os.time(),d=mrc.d}
bb.roomKUp=true
local Brc={}
for Crc,Drc in pairs(P.dg.roomK)do
table.insert(Brc,{s=Crc,at=type(Drc)==Hve[2124]and tonumber(Drc.at)or 0})
end
table.sort(Brc,function(Erc,Frc)
return Erc.at>Frc.at
end)
for Grc=31,#Brc do
P.dg.roomK[Brc[Grc].s]=nil
end
F.log(1,Hve[4064],string.format(Hve[4183],tostring(mrc.d),xrc,Arc))
end
function jb.roomDone(Hrc)
