P.simTeam.dg.stale=true
end
P.dg.playLast=nil
local Irc=tonumber(type(bb.ld._dungeon)==Hve[2124]and bb.ld._dungeon.depth)or(P.pending and tonumber(P.pending.depth))or 1
local Jrc=tostring(math.min(4,math.max(1,math.ceil(Irc/5))))
local Krc=P.dg.depth[Jrc]or{runs=0,wins=0}
Krc.runs,Krc.wins=(tonumber(Krc.runs)or 0)+1,(tonumber(Krc.wins)or 0)+(Hrc and 1 or 0)
P.dg.depth[Jrc]=Krc
if bb.pred and bb.pred.won==false then
local Lrc=type(P.dg.lossCalls)==Hve[2124]and P.dg.lossCalls or{}
Lrc.n,Lrc.won=(tonumber(Lrc.n)or 0)+1,(tonumber(Lrc.won)or 0)+(Hrc and 1 or 0)
P.dg.lossCalls=Lrc
end
local Mrc=jb.data()
local Nrc,Orc,Prc=jb.res(Mrc)
jb.note(string.format(Hve[4184],Irc,jb.ROOMS,Hrc and Hve[4185]or Hve[2875],Nrc,Orc,Prc,jb.lives(Mrc)))
P.dg.teams=type(P.dg.teams)==Hve[2124]and P.dg.teams or{}
local Qrc=P.dg.teams[W.teamSig()]or{w=0,l=0}
if Hrc then
Qrc.w=(tonumber(Qrc.w)or 0)+1
else
Qrc.l=(tonumber(Qrc.l)or 0)+1
end
P.dg.teams[W.teamSig()]=Qrc
if Hrc then
P.dg.lives=5
elseif P.dg.room and P.dg.room.d==Irc then
P.dg.lost=P.dg.lost or{}
local Rrc,Src=tostring(P.dg.room.seed),W.teamSig()
P.dg.lost[Rrc]=P.dg.lost[Rrc]or{}
P.dg.lost[Rrc][Src]=(P.dg.lost[Rrc][Src]or 0)+1
end
end
