function bb.buildPath()
bb.samples={}
local isc=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not isc then
return
end
for jsc,ksc in pairs(isc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[jsc.Name])then
local lsc={}
for msc,nsc in ipairs(ksc.points or{})do
table.insert(lsc,nsc.part.Position)
end
local osc=0
for psc=2,#lsc do
osc=osc+(lsc[psc]-lsc[psc-1]).Magnitude
end
local qsc=0
for rsc=2,#lsc do
local ssc,tsc=lsc[rsc-1],lsc[rsc]
local usc=(tsc-ssc).Magnitude
local vsc=math.max(1,math.floor(usc/2))
for wsc=0,vsc-1 do
local xsc=ssc:Lerp(tsc,wsc/vsc)
table.insert(bb.samples,{pos=xsc,prog=(qsc+usc*wsc/vsc)/math.max(1,osc),lane=jsc.Name})
end
qsc=qsc+usc
end
if lsc[#lsc]then
table.insert(bb.samples,{pos=lsc[#lsc],prog=1,lane=jsc.Name})
end
end
end
pcall(bb.readHidden,isc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local ysc=tonumber(bb.ld and bb.ld._portal_lanes)
local zsc=gb.laneList(bb.samples)
if ysc and ysc>=1 and zsc and#zsc>ysc then
bb.laneWant=ysc
end
bb.laneTotal=zsc and#zsc or 1
bb.countLanes()
end
function bb.readHidden(Asc)
local Bsc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(Bsc)~=Hve[2124]or not next(Bsc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local Csc
for Dsc,Esc in pairs(Asc)do
if Bsc[Dsc.Name]and type(Esc.points)==Hve[2124]and#Esc.points>=2 then
local Fsc={}
for Gsc,Hsc in ipairs(Esc.points)do
Fsc[Gsc]=U.flat(Hsc.part.Position)
end
local Isc={}
for Jsc,Ksc in ipairs(bb.samples)do
local Lsc=tostring(Ksc.lane)
Isc[Lsc]=Isc[Lsc]or{}
table.insert(Isc[Lsc],Ksc)
end
local Msc,Nsc
for Osc,Psc in pairs(Isc)do
local Qsc=0
for Rsc=1,#Fsc,math.max(1,math.floor(#Fsc/20))do
local Ssc=math.huge
for Tsc,Usc in ipairs(Psc)do
local Vsc=(U.flat(Usc.pos)-Fsc[Rsc]).Magnitude
if Vsc<Ssc then
Ssc=Vsc
end
end
Qsc=Qsc+Ssc
end
if not Nsc or Qsc<Nsc then
Msc,Nsc=Osc,Qsc
end
end
local Wsc,Xsc,Ysc,Zsc,_sc,atc={},nil,nil,nil,0,0
for btc,ctc in ipairs(Fsc)do
local dtc,etc=nil,math.huge
for ftc,gtc in ipairs(Isc[Msc])do
local htc=(U.flat(gtc.pos)-ctc).Magnitude
if htc<etc then
etc,dtc=htc,gtc.prog
end
end
atc=math.max(atc,etc)
if Ysc then
local itc=dtc-Ysc
local jtc=(itc>0.002 and 1)or(itc< -0.002 and-1)or Zsc
if Zsc and jtc and jtc~=Zsc then
table.insert(Wsc,math.floor(Ysc*1000+0.5)/1000)
end
Zsc,_sc=jtc or Zsc,_sc+math.abs(itc)
else
Xsc=dtc
end
Ysc=dtc
if btc%50==0 then
task.wait()
end
end
if Ysc and atc<=8 then
table.insert(Wsc,math.floor(Ysc*1000+0.5)/1000)
Csc=Csc or{}
Csc[Dsc.Name]={from=math.floor((Xsc or 0)*1000+0.5)/1000,len=math.floor(_sc*1000+0.5)/1000,turns=Wsc,road=Msc}
end
end
end
if not Csc then
return
end
local ktc=bb.ld.map
P.maps[ktc]=P.maps[ktc]or{}
local ltc=P.maps[ktc].hidden
P.maps[ktc].hidden=Csc
if type(ltc)~=Hve[2124]then
for mtc,ntc in pairs(Csc)do
F.log(1,Hve[2798],string.format(Hve[4199],mtc,ntc.len,tostring(ntc.road),math.floor((#ntc.turns-1)/2)))
end
F.saveSoon()
end
end
function bb.countLanes()
local otc,ptc,qtc={},0,0
for rtc,stc in ipairs(bb.samples)do
local ttc=tostring(stc.lane)
if not otc[ttc]then
ptc=ptc+1
end
otc[ttc]=(otc[ttc]or 0)+1
qtc=qtc+1
end
bb.laneCount={n=ptc,by=otc,avg=ptc>0 and qtc/ptc or 1}
if ptc>=2 then
local utc,vtc=pcall(gb.laneSep,bb.samples)
local wtc=P.maps[bb.mapKey()]
if utc and vtc and type(wtc)==Hve[2124]then
wtc.sep=vtc
end
end
end
bb.LANE_WAIT=3
function bb.portalLanes()
if not bb.laneWant or bb.laneCut then
return true
end
if bb.planning then
return false
end
local xtc,ytc={},0
for ztc,Atc in ipairs(workspace._UNITS:GetChildren())do
local Btc=Atc:FindFirstChild(Hve[2188])
if Btc and Btc:FindFirstChild(Hve[4200])and Btc.player.Value==nil and Btc:FindFirstChild(Hve[4201])and Atc:FindFirstChild(Hve[3386])then
local Ctc=tostring(Btc.lane.Value)
if not xtc[Ctc]then
xtc[Ctc]=true
ytc=ytc+1
end
end
end
if ytc==0 then
if U.now()-(bb.startT or U.now())>45 then
bb.laneWant=nil
F.log(1,Hve[2798],Hve[4202])
return true
end
return false
end
