local axc=_wc._stats
if not V.isFarm(axc.id.Value)and axc:FindFirstChild(Hve[2377])then
table.insert(Ywc,{p=U.flat(_wc:GetPivot().Position),r=axc.range.Value*(V.SUMMONER[axc.id.Value]and V.SUMMONER[axc.id.Value].reach or 1),air=bb.canAir(_wc)})
