if Bxc.hp>0 and Bxc.fly and Bxc.prog>cxc+0.02 then
yxc=true
end
end
end
local Dxc= #Ywc>0 and(bb.pressure or 0)>=bxc-0.08
return{covEnd=bxc,airEnd=cxc,leak=xxc,leakLane=zxc,covL=ixc,airLeak=yxc,push=Dxc,units= #Ywc}
end
