end
table.insert(gRc.wave,tonumber(jRc)or 0)
if tonumber(kRc)then
gRc.kills=type(gRc.kills)==Hve[2124]and gRc.kills or{}
table.insert(gRc.kills,math.floor(tonumber(kRc)))
while#gRc.kills>bb.LAYOUT_KEEP do
table.remove(gRc.kills,1)
end
end
while#gRc.sec>bb.LAYOUT_KEEP do
table.remove(gRc.sec,1)
