function bb.controlSpot(VRc,WRc)
if not bb.killZone()then
return nil
end
local XRc=gb.holds
if not XRc(VRc.id)or V.toggleOf(VRc.id)then
return nil
end
local YRc,ZRc,_Rc,aSc=1,0,0,{}
local bSc=bb.hurtSamples()
for cSc,dSc in ipairs(bb.mine or{})do
local eSc=dSc._stats
local fSc=eSc.id.Value
if eSc:FindFirstChild(Hve[2377])and not V.isFarm(fSc)and not V.allyBuff(fSc)then
local gSc,hSc=U.flat(dSc:GetPivot().Position),eSc.range.Value
if XRc(fSc)and not V.toggleOf(fSc)then
_Rc=_Rc+1
table.insert(aSc,{p=gSc,r=hSc})
else
for iSc,jSc in ipairs(bSc)do
if(U.flat(jSc.pos)-gSc).Magnitude<=hSc then
YRc,ZRc=math.min(YRc,jSc.prog),math.max(ZRc,jSc.prog)
end
end
end
end
end
if ZRc<=YRc then
YRc,ZRc=0.75,0.98
end
local kSc=(WRc or _Rc)+1
local lSc=({YRc,ZRc,(YRc+ZRc)/2,YRc-(ZRc-YRc)/2})[kSc]
if not lSc then
return nil
end
local mSc=V.range(VRc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local nSc={}
for oSc,pSc in ipairs(bb.cands)do
local qSc,rSc,sSc=U.flat(pSc),0,0
for tSc,uSc in ipairs(bSc)do
if(U.flat(uSc.pos)-qSc).Magnitude<=mSc then
sSc=sSc+1
if math.abs(uSc.prog-lSc)<=0.05 then
rSc=rSc+1
local vSc=U.flat(uSc.pos)
for wSc,xSc in ipairs(aSc)do
if(vSc-xSc.p).Magnitude<=xSc.r then
rSc=rSc-0.5
break
end
end
end
end
end
if rSc>0 then
table.insert(nSc,{pos=pSc,sc=rSc,cov=sSc})
end
if oSc%60==0 then
task.wait()
end
end
table.sort(nSc,function(ySc,zSc)
return ySc.sc>zSc.sc
end)
for ASc,BSc in ipairs(nSc)do
local CSc=bb.valid(BSc.pos,VRc.data)
if CSc then
F.log(1,Hve[4239],string.format(Hve[4412],V.name(VRc.id),bb.CONTROL_WORDS[kSc],math.floor(lSc*100+0.5)))
return CSc,BSc.cov,lSc
end
if ASc%20==0 then
task.wait()
end
end
return nil
end
function bb.holdSpot(DSc)
local ESc,FSc=gb.holds(DSc.id)
