end
local GSc,HSc={},0
for ISc,JSc in ipairs(bb.mine or{})do
local KSc=JSc._stats
local LSc=KSc.id.Value
if KSc:FindFirstChild(Hve[2377])and not V.isFarm(LSc)and not V.allyBuff(LSc)and LSc~=DSc.id then
local MSc,NSc=pcall(bb.liveDps,JSc,LSc)
NSc=MSc and tonumber(NSc)or 0
if NSc>0 then
table.insert(GSc,{p=U.flat(JSc:GetPivot().Position),r=KSc.range.Value,d=NSc})
HSc=HSc+NSc
end
