local SSc,TSc=U.flat(RSc.pos),0
for USc,VSc in ipairs(GSc)do
if(SSc-VSc.p).Magnitude<=VSc.r then
TSc=TSc+VSc.d
end
end
PSc[QSc]=TSc/HSc
end
local WSc=V.range(DSc.u,math.min(tonumber(FSc)or 0,3,V.rows(DSc.id).max))*((bb.info and tonumber(bb.info.rangeScale))or 1)
local XSc,YSc,ZSc
