for eTc,fTc in ipairs(OSc)do
if(U.flat(fTc.pos)-bTc).Magnitude<=WSc then
cTc=cTc+PSc[eTc]
dTc=dTc+1
end
end
if cTc>0 and(not YSc or cTc>YSc)then
local gTc=bb.valid(aTc,DSc.data)
