if OTc and HTc then
local PTc,QTc,RTc=false,U.flat(OTc),V.range(hTc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local STc=bb.depth and bb.depth.leakLane and tostring(bb.depth.leakLane)or nil
for TTc,UTc in ipairs(bb.hurtSamples())do
if UTc.prog>=HTc+0.02 and(not STc or tostring(UTc.lane)==STc)and(U.flat(UTc.pos)-QTc).Magnitude<=RTc then
