function bb.learn()
local Pdd=bb.calRun and bb.calRun.potBy
if type(Pdd)~=Hve[2124]then
return
end
pcall(bb.sampleHelpers,true)
local Qdd={}
for Rdd,Sdd in pairs(bb.ownDealt or{})do
if not V.isFarm(Sdd.id)then
Qdd[Sdd.id]=(Qdd[Sdd.id]or 0)+(tonumber(Sdd.v)or 0)
end
end
for Tdd,Udd in pairs(bb.helperDealt or{})do
if Udd.owner and V.SUMMONER[Udd.owner]and not V.droneHelper(Udd)then
Qdd[Udd.owner]=(Qdd[Udd.owner]or 0)+(tonumber(Udd.v)or 0)
end
end
local Vdd=type(bb.calRun.potExp)==Hve[2124]and bb.calRun.potExp or{}
local Wdd,Xdd=0,0
local Ydd={}
for Zdd,_dd in pairs(Pdd)do
if _dd>0 then
Wdd,Xdd=Wdd+(Qdd[Zdd]or 0),Xdd+_dd
local aed=tonumber(Vdd[Zdd])or _dd
if aed>0 then
table.insert(Ydd,{id=Zdd,r=(Qdd[Zdd]or 0)/aed,w=aed})
end
end
end
if Wdd<=0 or Xdd<=0 then
return
end
table.sort(Ydd,function(bed,ced)
return bed.r<ced.r
end)
local function ded(eed)
local ged,hed=0,0
for ied,jed in ipairs(Ydd)do
if jed.id~=eed then
ged=ged+jed.w
end
end
if ged<=0 then
return nil
end
for ked,led in ipairs(Ydd)do
if led.id~=eed then
hed=hed+led.w
if hed>=ged/2 then
return led.r
end
end
end
end
bb.lastEff={}
for med,ned in pairs(Pdd)do
local oed=ded(med)
if ned>0 and ned/Xdd>0.02 and oed and oed>0 then
local ped=P.learn[med]or{eff=1,n=0,v=6}
V.learnUp(med,ped)
local qed=math.max(0.02,0.25*math.sqrt(30/(30+ped.n)))
local sed=U.clamp(((Qdd[med]or 0)/ned)/oed,0.2,6)
bb.lastEff[med]=math.floor(sed*1000+0.5)/1000
ped.eff=ped.eff+(sed-ped.eff)*qed
ped.n=ped.n+1
P.learn[med]=ped
end
end
local ted=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if ted and next(bb.lastEff)then
P.mapLearn=type(P.mapLearn)==Hve[2124]and P.mapLearn or{}
local ued=type(P.mapLearn[ted])==Hve[2124]and P.mapLearn[ted]or{}
for ved,wed in pairs(bb.lastEff)do
local xed=type(ued[ved])==Hve[2124]and ued[ved]or{eff=wed,n=0,v=6}
if(tonumber(xed.v)or 0)<4 then
xed.eff,xed.v=(tonumber(xed.eff)or wed)*V.secRescale(ved),4
end
if(tonumber(xed.v)or 0)<5 then
xed.eff,xed.v=(tonumber(xed.eff)or wed)*(V.sumRescale(ved)or 1),5
end
if(tonumber(xed.v)or 0)<6 then
xed.eff,xed.v=(tonumber(xed.eff)or wed)*(1-(V.SUMMONER[ved]and V.SUMMONER[ved].droneShare or 0)),6
end
local yed=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(xed.n)or 0))))
xed.eff=(tonumber(xed.n)or 0)==0 and wed or((tonumber(xed.eff)or wed)+(wed-(tonumber(xed.eff)or wed))*yed)
xed.n=(tonumber(xed.n)or 0)+1
ued[ved]=xed
end
ued._at=os.time()
P.mapLearn[ted]=ued
if U.count(P.mapLearn)>80 then
local zed,Aed
for Bed,Ced in pairs(P.mapLearn)do
if not Aed or(tonumber(Ced._at)or 0)<Aed then
zed,Aed=Bed,tonumber(Ced._at)or 0
end
end
P.mapLearn[zed]=nil
end
end
end
function bb.randomTeam()
