if bb.money()>=Ejd then
local Gjd=Ajd and F.request(Hve[4697],Hve[4698],Ajd,pjd)or(not Ajd and F.request(Hve[2307],Hve[2505],pjd))
if Gjd then
F.log(1,Hve[4239],string.format(Hve[4699],Fjd,Ajd and Hve[4700]or Hve[1043],V.name(ijd.id)))
