end
local Qjd=(bb.pressure or 0)>=math.min(O.dangerReach,((bb.depth and bb.depth.units>0 and bb.depth.covEnd)or 1)*0.9)
local Rjd=bb.bestRate or 0
if Qjd or Rjd<=0 then
return
end
local Sjd=bb.wave()
local Tjd=math.max(0,(bb.total or 30)-Sjd)
local Ujd=bb.mergePlan
local Vjd=bb.airLow()
local Wjd,Xjd,Yjd
for Zjd,_jd in ipairs(bb.mine)do
local akd=_jd._stats
local bkd=akd.id.Value
local ckd=N.Units[bkd]
local dkd=akd:FindFirstChild(Hve[4241])and tonumber(akd.total_spent.Value)or 0
if ckd and not ckd.unsellable and dkd>0 and not V.allyBuff(bkd)and not V.idol(bkd)and not(Ujd and Ujd.id==bkd)then
local ekd,fkd
if V.isFarm(bkd)then
local gkd=akd:FindFirstChild(Hve[2233])and tonumber(akd.farm_amount.Value)or 0
local hkd=gkd*Tjd
if dkd>hkd*1.2 then
ekd=(dkd-hkd)*Rjd
fkd=string.format(Hve[4705],U.fmt(hkd),U.fmt(dkd))
end
elseif Sjd>=10 and Tjd>2 and dkd>=5000 and(bb.upRate[_jd]or 0)<Rjd/3 and bb.progressAt(_jd:GetPivot().Position)<0.8 and not(Vjd and bb.canAir(_jd))then
local ikd,jkd=pcall(bb.liveDps,_jd,bkd)
jkd=ikd and jkd or math.huge
if dkd*Rjd>3*jkd and jkd<0.1*(bb.teamDps or 0)then
ekd=dkd*Rjd-jkd
fkd=string.format(Hve[4706],U.fmt(dkd))
end
end
if ekd and(not Xjd or ekd>Xjd)then
Wjd,Xjd,Yjd=_jd,ekd,fkd
end
end
end
if not Wjd then
