local lkd=F.request(Hve[4697],Hve[4698],Njd,Wjd)
task.wait(1.5)
if lkd and(N.session().ingame_spells or{})[Njd]~=Hve[4690]then
bb.refunds=(bb.refunds or 0)+1
F.log(1,Hve[4683],string.format(Hve[4707],kkd,Yjd))
F.status(Hve[4568],Hve[4708]..kkd)
else
F.backoff(Hve[4697],15)
F.log(2,Hve[4683],Hve[4709]..kkd)
end
bb.spellBusy=false
end)
end
bb.BASE_WIN,bb.BASE_MARGIN,bb.BASE_SOON,bb.BASE_END=10,1.3,45,0.97
function bb.baseVerdict(mkd,nkd)
local okd=(nkd.t or 0)-(mkd.t or 0)
if okd<bb.BASE_WIN-1 then
return false
end
local pkd=((tonumber(mkd.base)or 0)-(tonumber(nkd.base)or 0))/okd
if pkd<=0 or(tonumber(nkd.base)or 0)<=0 then
return false
end
local qkd=nkd.base/pkd
local rkd,skd=0,0
local tkd,ukd=mkd.foes or{},nkd.foes or{}
for vkd,wkd in pairs(ukd)do
if wkd.prog>=bb.BASE_END then
rkd=rkd+wkd.hp
local xkd=tkd[vkd]
if xkd then
skd=skd+math.max(0,xkd.hp-wkd.hp)
end
end
end
for ykd,zkd in pairs(tkd)do
if zkd.prog>=bb.BASE_END and not ukd[ykd]then
skd=skd+zkd.hp
end
end
if rkd<=0 then
return false
end
local Akd=skd/okd
local Bkd=Akd>0 and rkd/Akd or math.huge
local Ckd={baseTime=qkd,loss=pkd,atEnd=rkd,rate=Akd,killTime=Bkd}
return qkd<bb.BASE_SOON and Bkd>qkd*bb.BASE_MARGIN,Ckd
end
