bb.LEAK_WIN,bb.LEAK_SOON,bb.LEAK_MIN,bb.LEAK_MARGIN,bb.LEAK_AHEAD=3,12,3,1.5,6
function bb.leakAhead(bld)
local cld=0
local dld=U.flat(bld.pos)
for eld,fld in ipairs(bb.mine or{})do
local gld=fld:FindFirstChild(Hve[2188])
local hld=gld and gld:FindFirstChild(Hve[2502])
local ild=gld and gld:FindFirstChild(Hve[2377])
if hld and ild and not V.isFarm(hld.Value)and not V.allyBuff(hld.Value)then
local jld,kld=U.flat(fld:GetPivot().Position),ild.Value
if(not bld.fly or bb.canAir(fld))and(jld-dld).Magnitude>kld then
for lld,mld in ipairs(bb.samples or{})do
if mld.prog>bld.prog and(U.flat(mld.pos)-jld).Magnitude<=kld then
cld=cld+1
break
end
end
end
end
end
return cld
end
function bb.leakStep(nld)
if not nld then
if bb.kind~=Hve[2145]or bb.bailed or O.bailOut==false or bb.random or bb.infinite then
return
end
end
local pld=tostring(P.dg.room and P.dg.room.seed)
P.dg.bails=type(P.dg.bails)==Hve[2124]and P.dg.bails or{}
if not nld and(tonumber(P.dg.bails[pld])or 0)>=bb.BAIL_MAX then
return
end
local qld=workspace:FindFirstChild(Hve[4722])and workspace._BASES:FindFirstChild(Hve[4200])
local rld=qld and qld:FindFirstChild(Hve[4433])and qld.base:FindFirstChild(Hve[4434])
local sld=rld and rld:FindFirstChildOfClass(Hve[2520])
if not sld or sld.Health<=0 then
return
end
local tld=(bb.info and tonumber(bb.info.baseRel))or gb.PRIOR.baseRel
local uld=U.now()
bb.leakTrack=bb.leakTrack or{}
local vld=bb.leakTrack
local wld,xld={},nil
for yld,zld in ipairs(bb.enemies or{})do
if zld.m then
wld[zld.m]=true
local Ald,Bld=tonumber(zld.hp)or 0,tonumber(zld.prog)or 0
local Cld=vld[zld.m]
if not Cld then
vld[zld.m]={t=uld,hp=Ald,prog=Bld}
else
if uld-Cld.t>=bb.LEAK_WIN then
Cld.pace,Cld.net=(Bld-Cld.prog)/(uld-Cld.t),(Cld.hp-Ald)/(uld-Cld.t)
Cld.t,Cld.hp,Cld.prog=uld,Ald,Bld
end
if Cld.pace and Cld.pace>0 and Ald>0 then
local Dld=(1-Bld)/Cld.pace
local Eld=math.max(0,Cld.net or 0)
local Fld=Ald-Eld*Dld
if Fld>0 and Dld<=bb.LEAK_SOON and Dld>=bb.LEAK_MIN then
local Gld=zld.m:FindFirstChildOfClass(Hve[2520])
local Hld=sld.Health/math.max(1,tld*(Gld and Gld.MaxHealth or Ald))
local Ild=Eld>0 and Fld/Eld or math.huge
if Ild>Hld*bb.LEAK_MARGIN and(Dld<=bb.LEAK_AHEAD or bb.leakAhead(zld)==0)and(not xld or Dld<xld.left)then
xld={left=Dld,arriving=Fld,net=Eld,baseTime=Hld,hp=Ald}
end
end
end
end
end
end
for Jld in pairs(vld)do
if not wld[Jld]then
vld[Jld]=nil
end
end
if nld then
return xld~=nil,xld
end
if not xld then
return
end
bb.bailNote(pld,Hve[4716])
F.log(1,Hve[2798],string.format(Hve[4725],bb.wave(),tonumber(bb.total)or 0,math.floor(xld.left+0.5),U.fmt(xld.hp),U.fmt(xld.arriving),U.fmt(xld.net),xld.baseTime))
pcall(F.saveNow)
bb.toLobby(Hve[4724])
end
