function bb.allPast(Kld)
local Lld={}
for Mld,Nld in ipairs(bb.mine or{})do
local Old=Nld._stats
local Pld=Old.id.Value
if not V.isFarm(Pld)and not V.allyBuff(Pld)and Old:FindFirstChild(Hve[2377])then
local Qld=tonumber(Old.range.Value)or 0
local Rld=bb.coverMax[Nld]
if not(Rld and Rld.r==Qld)then
local Sld,Tld=U.flat(Nld:GetPivot().Position),-1
for Uld,Vld in ipairs(bb.samples or{})do
if Vld.prog>Tld and(U.flat(Vld.pos)-Sld).Magnitude<=Qld then
Tld=Vld.prog
end
end
Rld={r=Qld,far=Tld}
bb.coverMax[Nld]=Rld
end
table.insert(Lld,{far=Rld.far,air=bb.canAir(Nld)})
end
end
if#Lld==0 then
return false
end
for Wld,Xld in ipairs(Kld)do
for Yld,Zld in ipairs(Lld)do
if(not Xld.fly or Zld.air)and Zld.far>=(tonumber(Xld.prog)or 0)then
return false
end
end
end
return true
end
function bb.fbTick()
local _ld=bb.info and bb.info.final
if not(_ld and _ld.cfg)then
return
end
local amd=type(bb.info.configs)==Hve[2124]and bb.info.configs[_ld.cfg]
local bmd=type(amd)==Hve[2124]and amd.unit_id or _ld.cfg
local cmd
for dmd,emd in ipairs(bb.enemies or{})do
local fmd=emd.m and emd.m:FindFirstChild(Hve[2188])
if fmd and fmd:FindFirstChild(Hve[2502])and fmd.id.Value==bmd then
cmd=emd
break
end
end
local gmd=bb.fb
if not cmd then
if gmd and not gmd.gone then
gmd.gone=U.now()
end
return
end
local hmd=cmd.m:FindFirstChildOfClass(Hve[2520])
local imd=(hmd and hmd.MaxHealth>0)and hmd.MaxHealth or cmd.hp
local jmd=(N.Units[bmd]and N.Units[bmd].name)or bmd
if not gmd or gmd.m~=cmd.m then
gmd={m=cmd.m,id=bmd,name=jmd,wave=bb.wave(),t0=U.now(),max=imd,low=1,assassin=_ld.assassin,beatAt=tonumber(_ld.beatAt)or 0.5,walk=_ld.walk}
bb.fb=gmd
if _ld.assassin then
F.log(1,Hve[2798],string.format(Hve[4726],jmd,gmd.wave,U.fmt(imd),math.floor(gmd.beatAt*100+0.5)))
end
end
gmd.e=cmd
gmd.share=imd>0 and cmd.hp/imd or 1
gmd.low=math.min(gmd.low,gmd.share)
local kmd,lmd=pcall(N.PATH.get_unit_path_progress,cmd.m)
gmd.gp=kmd and tonumber(lmd)or nil
if gmd.assassin and not gmd.beaten and gmd.share<=gmd.beatAt+0.005 then
gmd.beaten=U.now()
F.log(1,Hve[2798],string.format(Hve[4727],jmd,math.floor(gmd.share*100+0.5)))
end
if#(bb.enemies or{})==1 and bb.total and bb.wave()>=bb.total then
gmd.aloneT=gmd.aloneT or U.now()
gmd.alone=math.max(gmd.alone or 0,U.now()-gmd.aloneT)
else
gmd.aloneT=nil
end
end
function bb.fbEnd(mmd)
