return pmd and math.floor(pmd*1000+0.5)/1000 or nil
end
return{id=nmd.id,wave=nmd.wave,hp=math.floor(nmd.max),left=nmd.gone and 0 or omd(nmd.share),low=omd(nmd.low),lane=omd(nmd.gp),alone=nmd.alone and math.floor(nmd.alone)or nil,sec=math.floor(U.now()-nmd.t0),won=mmd and true or false,assassin=nmd.assassin or nil}
