function bb.bossStep()
bb.focus=nil
pcall(bb.fbTick)
if bb.random or bb.infinite or not(bb.total and bb.wave()>=bb.total)then
return
end
local tmd=bb.enemies or{}
local umd=bb.fb
if umd and umd.beaten and umd.m then
local vmd={}
for wmd,xmd in ipairs(tmd)do
if xmd.m~=umd.m then
table.insert(vmd,xmd)
end
end
tmd=vmd
end
for ymd,zmd in ipairs(tmd)do
local Amd=zmd.m and zmd.m:FindFirstChildOfClass(Hve[2520])
if Amd and Amd.MaxHealth>((bb.bossTop and bb.bossTop.hp)or 0)then
local Bmd=zmd.m:FindFirstChild(Hve[2188])
bb.bossTop={hp=Amd.MaxHealth,id=Bmd and Bmd:FindFirstChild(Hve[2502])and Bmd.id.Value,regen=Bmd and Bmd:FindFirstChild(Hve[4728])and Bmd.Regen.Value}
end
end
if#tmd<=2 and bb.bossTop and not bb.bossSaid then
bb.bossSaid=true
pcall(function()
local Cmd=0
if bb.info then
for Dmd,Emd in ipairs((gb.wave(bb.info,bb.total)))do
if Emd.boss and Emd.hp>Cmd then
Cmd=Emd.hp
end
end
end
F.log(1,Hve[2798],string.format(Hve[4729],tostring(bb.bossTop.id),bb.bossTop.hp,tostring(bb.bossTop.regen),Cmd))
end)
end
local Fmd= #tmd>2 and#tmd<=bb.FOCUS_MAX and bb.allPast(tmd)
if#tmd==0 or(#tmd>2 and not Fmd)then
bb.focusTrack=nil
return
end
if Fmd and not bb.allPastSaid then
bb.allPastSaid=true
F.log(1,Hve[2798],string.format(Hve[4730],#tmd))
end
local Gmd,Hmd=nil,1
for Imd,Jmd in ipairs(tmd)do
if not Gmd or Jmd.hp>Gmd.hp then
Gmd=Jmd
end
Hmd=math.min(Hmd,Jmd.prog)
end
bb.focus={pos=Gmd.pos,prog=Gmd.prog,fly=Gmd.fly,m=Gmd.m}
local Kmd=umd and not umd.beaten and umd.m==Gmd.m and type(umd.walk)==Hve[2124]and umd.gp and umd or nil
local Lmd=Kmd and Kmd.gp or Gmd.prog
local Mmd=U.now()
local Nmd=bb.focusTrack
if not Nmd or Nmd.m~=Gmd.m then
bb.focusTrack={m=Gmd.m,t=Mmd,hp=Gmd.hp,prog=Lmd}
return
end
if Mmd-Nmd.t>=10 then
Nmd.net,Nmd.rate=(Nmd.hp-Gmd.hp)/(Mmd-Nmd.t),(Lmd-Nmd.prog)/(Mmd-Nmd.t)
Nmd.t,Nmd.hp,Nmd.prog=Mmd,Gmd.hp,Lmd
end
if not Nmd.rate or Nmd.rate<=0 then
return
end
local Omd,Pmd=Hmd,1
if Kmd then
Omd,Pmd=gb.walkSpan(Kmd.walk,Kmd.gp*Kmd.walk.len)
end
local Qmd=U.flat(Gmd.pos)
local Rmd,Smd,Tmd,Umd={},{},0,0
for Vmd,Wmd in ipairs(bb.mine or{})do
