local Pnd=bb.valid(Ond,Gnd.data)
Mnd=Mnd+1
if Mnd%40==0 then
task.wait()
end
if Pnd then
local Qnd,Rnd=0,U.flat(Pnd)
for Snd,Tnd in ipairs(bb.hurtSamples())do
if Tnd.prog>=Hnd.prog and(U.flat(Tnd.pos)-Rnd).Magnitude<=Ind then
Qnd=Qnd+1
end
end
